import{state as checkoutState,dispose}from"../../../store/checkout/index";import{withDefaultData}from"../index";describe("withDefaultData metadata merge",(()=>{beforeEach((()=>{dispose(),window.scData={page_id:42},checkoutState.product={id:"prod_1"}})),it("keeps both the caller keys and the composed keys",(()=>{const{metadata:e}=withDefaultData({metadata:{gift_note:"wrap it"}});expect(e).toEqual({gift_note:"wrap it",page_id:42,buy_page_product_id:"prod_1",page_url:window.location.href})})),it("does not let the caller clobber the composed keys",(()=>{const{metadata:e}=withDefaultData({metadata:{page_id:"evil",page_url:"https://evil.test/",buy_page_product_id:"prod_evil"}});expect(e.page_id).toBe(42),expect(e.page_url).toBe(window.location.href),expect(e.buy_page_product_id).toBe("prod_1")})),it("leaves a no-metadata call unchanged and keeps caller top-level overrides",(()=>{const e=withDefaultData({email:"a@b.com",live_mode:!1});expect(e.email).toBe("a@b.com"),expect(e.live_mode).toBe(!1),expect(e.metadata).toEqual({page_id:42,buy_page_product_id:"prod_1",page_url:window.location.href})}))}));